"use client"

import {
  forwardRef,
  useCallback,
  useId,
  useImperativeHandle,
  type KeyboardEvent,
  type ReactNode,
} from "react"

import {
  useDurationInput,
  type UseDurationInputOptions,
} from "./use-duration-input"

export type DurationLayout = "text" | "segmented" | "presets"

export interface DurationInputProps extends UseDurationInputOptions {
  label?: ReactNode
  hint?: ReactNode
  /** PRD §6. `text` is fastest for keyboard users; `segmented` is unambiguous. */
  layout?: DurationLayout
  /** Show the normalised value as a trailing affix. Default true. */
  showNormalised?: boolean
}

const SEGMENTS = [
  { unit: "h" as const, label: "hours", max: 999, width: 34 },
  { unit: "m" as const, label: "minutes", max: 59, width: 26 },
  { unit: "s" as const, label: "seconds", max: 59, width: 26 },
]

export const DurationInput = forwardRef<HTMLInputElement, DurationInputProps>(
  function DurationInput(
    { label, hint, layout = "text", showNormalised = true, className, id: idProp, ...rest },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useDurationInput({ ...rest, id })
    const {
      inputProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      display,
      segments,
      setSegment,
      presets,
      activePreset,
      applyPreset,
    } = api

    useImperativeHandle(
      ref,
      () =>
        inputProps.ref.current ??
        ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement),
      [inputProps.ref],
    )

    // Arrow keys on a segment step it and wrap, which is what people expect
    // from anything that looks like a clock.
    const onSegmentKey = useCallback(
      (unit: "h" | "m" | "s", maxValue: number) =>
        (e: KeyboardEvent<HTMLInputElement>) => {
          const step = e.key === "ArrowUp" ? 1 : e.key === "ArrowDown" ? -1 : 0
          if (!step) return
          e.preventDefault()
          let next = segments[unit] + step
          if (next < 0) next = maxValue
          if (next > maxValue) next = 0
          setSegment(unit, next)
        },
      [segments, setSegment],
    )

    const invalid = ariaProps["aria-invalid"] ? "true" : undefined

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        {layout === "segmented" ? (
          <div className="inputcn-segfield" data-invalid={invalid}>
            {SEGMENTS.map(({ unit, label: name, max, width }, i) => (
              <span className="inputcn-seg" key={unit}>
                {i > 0 ? <span className="inputcn-seg-gap" aria-hidden="true" /> : null}
                <input
                  id={i === 0 ? id : undefined}
                  className="inputcn-seg-input"
                  style={{ width }}
                  value={String(segments[unit]).padStart(2, "0")}
                  inputMode="numeric"
                  autoComplete="off"
                  aria-label={name}
                  disabled={rest.disabled}
                  readOnly={rest.readOnly}
                  onFocus={(e) => e.currentTarget.select()}
                  onKeyDown={onSegmentKey(unit, max)}
                  onChange={(e) => {
                    const n = Number(e.currentTarget.value.replace(/\D/g, "").slice(-3))
                    setSegment(unit, Math.min(Number.isNaN(n) ? 0 : n, max))
                  }}
                  {...(i === 0 ? ariaProps : {})}
                />
                <span className="inputcn-seg-unit" aria-hidden="true">
                  {unit}
                </span>
              </span>
            ))}
          </div>
        ) : layout === "presets" ? (
          <>
            <div className="inputcn-presets" role="group" aria-label="Common durations">
              {presets.map((p) => (
                <button
                  key={p}
                  type="button"
                  className="inputcn-pill"
                  aria-pressed={p === activePreset}
                  disabled={rest.disabled}
                  onClick={() => applyPreset(p)}
                >
                  {p}
                </button>
              ))}
            </div>
            <div className="inputcn-group" data-invalid={invalid} style={{ marginTop: 9 }}>
              <input
                {...inputProps}
                {...ariaProps}
                id={id}
                className="inputcn-bare"
                placeholder="Custom…"
                aria-label={rest["aria-label"] ?? "Custom duration"}
              />
              {showNormalised && display ? (
                <span className="inputcn-affix inputcn-affix-right" aria-hidden="true">
                  {display}
                </span>
              ) : null}
            </div>
          </>
        ) : (
          <div className="inputcn-group" data-invalid={invalid}>
            <input
              {...inputProps}
              {...ariaProps}
              id={id}
              className="inputcn-bare"
              aria-label={rest["aria-label"]}
              aria-labelledby={rest["aria-labelledby"]}
            />
            {showNormalised && display && display !== inputProps.value ? (
              <span className="inputcn-affix inputcn-affix-right" aria-hidden="true">
                {display}
              </span>
            ) : null}
          </div>
        )}

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import {
  custom,
  max as maxRule,
  min as minRule,
  multipleOf as multipleOfRule,
  required as requiredRule,
  rules,
} from "@inputcn/core/validity"

import {
  formatDuration,
  fromSegments,
  parseDuration,
  parsePastedDuration,
  toISO8601,
  toSegments,
  type DurationUnit,
} from "./duration"

/** Bounds accept human text so the prop reads like the rule: min="5m". */
export type DurationBound = number | string

export interface DurationConstraints {
  min?: DurationBound
  max?: DurationBound
  /** Must be a whole multiple of this. Accepts "15m". */
  multipleOf?: DurationBound
  /** Largest unit shown when formatting. Default "d". */
  maxUnit?: DurationUnit
}

export interface UseDurationInputOptions
  extends BaseFieldProps<number>,
    DurationConstraints {
  /** What a bare number means. Default "m". */
  bareUnit?: DurationUnit
  /** Presets offered by the `presets` layout. */
  presets?: readonly string[]
}

export interface UseDurationInputResult extends UseFieldResult<number> {
  /** Normalised human text for the current value. */
  display: string
  iso: string
  segments: { h: number; m: number; s: number }
  setSegment: (unit: "h" | "m" | "s", n: number) => void
  presets: readonly string[]
  /** The preset matching the current value, if any. */
  activePreset: string | undefined
  applyPreset: (text: string) => void
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    onBlur: () => void
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    autoComplete: "off"
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
}

const DEFAULT_PRESETS = ["5m", "15m", "30m", "1h", "4h", "1d"] as const

/** Bounds may be written as text; resolve once. */
function seconds(bound: DurationBound | undefined, bareUnit: DurationUnit): number | undefined {
  if (bound === undefined) return undefined
  return typeof bound === "number" ? bound : parseDuration(bound, { bareUnit })
}

export function useDurationInput(
  options: UseDurationInputOptions,
): UseDurationInputResult {
  const {
    bareUnit = "m",
    maxUnit = "d",
    min,
    max,
    multipleOf,
    presets = DEFAULT_PRESETS,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const minS = useMemo(() => seconds(min, bareUnit), [min, bareUnit])
  const maxS = useMemo(() => seconds(max, bareUnit), [max, bareUnit])
  const stepS = useMemo(() => seconds(multipleOf, bareUnit), [multipleOf, bareUnit])

  const asText = useCallback((s: number) => formatDuration(s, { maxUnit }), [maxUnit])

  const ruleList = useMemo<ReadonlyArray<Rule<number>>>(
    () =>
      rules<number>(
        requiredRule<number>(required),
        minRule(minS, asText),
        maxRule(maxS, asText),
        multipleOfRule(stepS, asText),
        custom<number>(validate),
      ),
    [required, minS, maxS, stepS, validate, asText],
  )

  const field = useField<number>({
    component: "DurationInput",
    emptyValue: 0,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
    serialize: (v) => String(v),
  })

  const { value, setValue } = field
  const ref = useRef<HTMLInputElement | null>(null)

  // While typing, show exactly what was typed — reformatting "2h 3" into
  // "2h 3m" mid-keystroke makes the next character land in the wrong place.
  const [draft, setDraft] = useState<string | null>(null)
  const normalised = formatDuration(value, { maxUnit })
  const display = draft ?? normalised

  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = e.currentTarget.value
      setDraft(text)
      setValue(parseDuration(text, { bareUnit }))
    },
    [disabled, readOnly, setValue, bareUnit],
  )

  const onBlur = useCallback(() => setDraft(null), [])

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      const parsed = parsePastedDuration(text, { bareUnit })
      if (parsed === null) return
      setDraft(null)
      setValue(parsed)
    },
    [disabled, readOnly, setValue, bareUnit],
  )

  const segments = useMemo(() => toSegments(value), [value])

  const setSegment = useCallback(
    (unit: "h" | "m" | "s", n: number) => {
      if (disabled || readOnly) return
      const next = { ...toSegments(value), [unit]: Math.max(0, n) }
      setDraft(null)
      setValue(fromSegments(next.h, next.m, next.s))
    },
    [disabled, readOnly, value, setValue],
  )

  const presetSeconds = useMemo(
    () => presets.map((p) => parseDuration(p, { bareUnit })),
    [presets, bareUnit],
  )

  const activePreset = useMemo(() => {
    const i = presetSeconds.indexOf(value)
    return i === -1 ? undefined : presets[i]
  }, [presetSeconds, presets, value])

  const applyPreset = useCallback(
    (text: string) => {
      if (disabled || readOnly) return
      setDraft(null)
      setValue(parseDuration(text, { bareUnit }))
    },
    [disabled, readOnly, setValue, bareUnit],
  )

  const inputProps = useMemo(
    () => ({
      ref,
      value: display,
      onChange,
      onBlur,
      onPaste,
      autoComplete: "off" as const,
      disabled,
      readOnly,
      placeholder: placeholder ?? "2h 30m",
    }),
    [display, onChange, onBlur, onPaste, disabled, readOnly, placeholder],
  )

  return {
    ...field,
    display,
    iso: toISO8601(value),
    segments,
    setSegment,
    presets,
    activePreset,
    applyPreset,
    inputProps,
  }
}

/**
 * Duration parsing and formatting. Framework-free.
 *
 * Canonical value is SECONDS as an integer.
 *
 * No substrate library exists for this — everyone writes their own regex and
 * disagrees about what a bare number means. The rule here is explicit and
 * documented: a bare number is MINUTES, because "timeout: 30" overwhelmingly
 * means half an hour rather than half a minute. Configurable, never guessed.
 */

import { scrub } from "@inputcn/core/paste"

export type DurationUnit = "d" | "h" | "m" | "s"

export const UNIT_SECONDS: Readonly<Record<DurationUnit, number>> = {
  d: 86_400,
  h: 3_600,
  m: 60,
  s: 1,
}

/** Longest-first so "min" is matched before "m". */
const UNIT_WORDS: ReadonlyArray<readonly [RegExp, DurationUnit]> = [
  [/^(days?|d)$/i, "d"],
  [/^(hours?|hrs?|h)$/i, "h"],
  [/^(minutes?|mins?|m)$/i, "m"],
  [/^(seconds?|secs?|s)$/i, "s"],
]

// Hoisted: these run on every keystroke.
const CLOCK_RE = /^(\d+):(\d{1,2})(?::(\d{1,2}))?$/
const TOKEN_RE = /(\d+(?:[.,]\d+)?)\s*([a-z]*)/gi

function unitOf(word: string, fallback: DurationUnit): DurationUnit {
  if (!word) return fallback
  for (const [re, unit] of UNIT_WORDS) {
    if (re.test(word)) return unit
  }
  return fallback
}

export interface ParseDurationOptions {
  /** What a bare number means. Default `"m"`. */
  bareUnit?: DurationUnit
}

/**
 * Parse human duration text into seconds.
 *
 * Accepts `"2h 30m"`, `"2h30"`, `"150m"`, `"2:30"`, `"1.5h"`, `"90 minutes"`.
 * Returns 0 for anything unparseable rather than NaN, so callers never have to
 * guard arithmetic.
 */
export function parseDuration(
  input: string,
  { bareUnit = "m" }: ParseDurationOptions = {},
): number {
  const text = scrub(input).toLowerCase()
  if (!text) return 0

  // Clock notation is unambiguous and must be handled before token scanning,
  // which would otherwise read "2:30" as two separate bare numbers.
  const clock = CLOCK_RE.exec(text)
  if (clock) {
    const h = Number(clock[1])
    const m = Number(clock[2])
    const s = clock[3] === undefined ? 0 : Number(clock[3])
    return h * 3600 + m * 60 + s
  }

  let total = 0
  let matched = false
  // Reset: TOKEN_RE is /g and carries lastIndex between calls.
  TOKEN_RE.lastIndex = 0
  let m: RegExpExecArray | null
  while ((m = TOKEN_RE.exec(text)) !== null) {
    const n = Number.parseFloat(m[1]!.replace(",", "."))
    if (!Number.isFinite(n)) continue
    matched = true
    total += n * UNIT_SECONDS[unitOf(m[2] ?? "", bareUnit)]
  }

  return matched ? Math.round(total) : 0
}

export interface FormatDurationOptions {
  /** Largest unit to use. Default `"d"`. */
  maxUnit?: DurationUnit
  /** Show at most this many units. Default 2 — "1h 30m", not "1h 30m 0s". */
  maxParts?: number
  /** Text for a zero duration. Default `""`. */
  zero?: string
}

const ORDER: readonly DurationUnit[] = ["d", "h", "m", "s"]

/** Seconds → compact human text. `5400` → `"1h 30m"`. */
export function formatDuration(
  seconds: number,
  { maxUnit = "d", maxParts = 2, zero = "" }: FormatDurationOptions = {},
): string {
  if (!Number.isFinite(seconds) || seconds === 0) return zero

  const negative = seconds < 0
  let rest = Math.abs(Math.round(seconds))
  const startAt = ORDER.indexOf(maxUnit)
  const parts: string[] = []

  for (let i = startAt; i < ORDER.length; i++) {
    const unit = ORDER[i]!
    const size = UNIT_SECONDS[unit]
    const n = Math.floor(rest / size)
    if (n > 0) {
      parts.push(`${n}${unit}`)
      rest -= n * size
    }
    if (parts.length >= maxParts) break
  }

  if (parts.length === 0) return zero
  return (negative ? "-" : "") + parts.join(" ")
}

/** Seconds → ISO 8601 duration. `5400` → `"PT1H30M"`. */
export function toISO8601(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds === 0) return "PT0S"
  let rest = Math.abs(Math.round(seconds))

  const d = Math.floor(rest / 86_400)
  rest -= d * 86_400
  const h = Math.floor(rest / 3_600)
  rest -= h * 3_600
  const m = Math.floor(rest / 60)
  const s = rest - m * 60

  const time = [h && `${h}H`, m && `${m}M`, s && `${s}S`].filter(Boolean).join("")
  const date = d ? `${d}D` : ""
  // "PT0S" is the canonical zero; a bare "P" is not valid.
  return `P${date}${time ? `T${time}` : d ? "" : "T0S"}`
}

/** Split seconds into whole hours, minutes and seconds for a segmented UI. */
export function toSegments(seconds: number): { h: number; m: number; s: number } {
  const total = Math.max(0, Math.round(seconds))
  const h = Math.floor(total / 3600)
  const m = Math.floor((total % 3600) / 60)
  return { h, m, s: total % 60 }
}

export function fromSegments(h: number, m: number, s: number): number {
  return Math.max(0, h) * 3600 + Math.max(0, m) * 60 + Math.max(0, s)
}

/** Smart paste — the same parser, since it is already tolerant by design. */
export function parsePastedDuration(
  input: string,
  options?: ParseDurationOptions,
): number | null {
  const text = scrub(input)
  if (!text || !/\d/.test(text)) return null
  return parseDuration(text, options)
}
